int send_tcp_messages(struct TCP_Server_Info *server, struct kvec *iov, size_t n_vec, size_t *sent) {
    struct msghdr msg = {0};
    size_t total_sent = 0;
    ssize_t bytes = 0;
    size_t i = 0;

    msg.msg_iov = iov;
    msg.msg_iovlen = n_vec;

    do {
        bytes = sendmsg(server->sock, &msg, 0);
        if (bytes < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            return -errno;
        }

        total_sent += bytes;

        for (i = 0; i < n_vec; i++) {
            if (bytes >= iov[i].iov_len) {
                bytes -= iov[i].iov_len;
                iov[i].iov_base = (void *)((char *)iov[i].iov_base + iov[i].iov_len);
                iov[i].iov_len = 0;
            } else {
                iov[i].iov_base = (void *)((char *)iov[i].iov_base + bytes);
                iov[i].iov_len -= bytes;
                break;
            }
        }

        if (total_sent == 0 && i == n_vec) {
            break;
        }
    } while (bytes > 0);

    if (sent) {
        *sent = total_sent;
    }

    if (total_sent == 0 && errno == 0) {
        return -ENOTCONN;
    }

    return total_sent;
}

