int sendmsg_to_tcp_server(struct TCP_Server_Info *server, struct kvec *iov, size_t n_vec, size_t *sent) {
    size_t total_sent = 0;
    ssize_t bytes;
    struct msghdr msg = {0};

    msg.msg_iov = iov;
    msg.msg_iovlen = n_vec;

    do {
        bytes = writev(server->sock, iov, n_vec);
        if (bytes < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue; // Non-blocking send, retry
            } else {
                return -errno; // Error occurred
            }
        }

        total_sent += bytes;

        // Adjust iov for remaining data
        size_t i;
        ssize_t remaining = bytes;
        for (i = 0; i < n_vec && remaining > 0; i++) {
            if (iov[i].iov_len <= remaining) {
                remaining -= iov[i].iov_len;
                iov++;
                n_vec--;
            } else {
                iov[i].iov_base += remaining;
                iov[i].iov_len -= remaining;
                remaining = 0;
            }
        }
    } while (n_vec > 0 && bytes > 0);

    *sent = total_sent;
    return total_sent;
}

int sendmsg_to_tcp_server(struct TCP_Server_Info *server, struct kvec *iov, size_t n_vec, size_t *sent) {
    ssize_t bytes_sent;
    size_t total_sent = 0;
    int ret = 0;
    size_t i = 0;

    while (i < n_vec) {
        bytes_sent = writev(server->sock, &iov[i], n_vec - i);
        if (bytes_sent < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            } else {
                ret = -errno;
                break;
            }
        }

        total_sent += bytes_sent;
        *sent = total_sent;

        // Update the iov accordingly if only part of the data was sent
        while (i < n_vec && bytes_sent > 0) {
            if (iov[i].iov_len <= bytes_sent) {
                bytes_sent -= iov[i].iov_len;
                i++;
            } else {
                iov[i].iov_base = (char *)iov[i].iov_base + bytes_sent;
                iov[i].iov_len -= bytes_sent;
                bytes_sent = 0;
            }
        }

        if (bytes_sent > 0) {
            // Partial send, retry
            continue;
        }
    }

    if (ret == 0) {
        ret = total_sent;
    }

    return ret;
}
